import{_ as a,o as i,c as t,a4 as r}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Litigation Compatibility Alias and Bhadra Audit","description":"","frontmatter":{},"headers":[],"relativePath":"reference/35-litigation-evidence-audit.md","filePath":"reference/35-litigation-evidence-audit.md","lastUpdated":1788593217000}'),o={name:"reference/35-litigation-evidence-audit.md"};function s(n,e,d,c,l,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="litigation-compatibility-alias-and-bhadra-audit" tabindex="-1">Litigation Compatibility Alias and Bhadra Audit <a class="header-anchor" href="#litigation-compatibility-alias-and-bhadra-audit" aria-label="Permalink to &quot;Litigation Compatibility Alias and Bhadra Audit&quot;">​</a></h1><h2 id="corrected-product-boundary" tabindex="-1">Corrected product boundary <a class="header-anchor" href="#corrected-product-boundary" aria-label="Permalink to &quot;Corrected product boundary&quot;">​</a></h2><p><code>litigation</code> is retained only as a backward-compatible Python/MCP alias for <code>court</code>, whose verified scope is filing or initiating a lawsuit. It is no longer a separate rule profile, does not appear in the browser selector, and does not claim to time hearings, responses, settlements, appeals, contests or case outcomes.</p><p>This removes three unsupported behaviors from the former duplicate profile: the Jaya-family reward, Purna-family penalty and Tuesday reward. It also removes the activity-specific Bhadra Puchha bonus. Alias resolution happens before rule lookup, so legacy callers receive the exact <code>muhurta.court.filing_lawsuit</code> profile and the MCP response discloses <code>alias_of: court</code> and <code>resolved_activity: court</code>.</p><h2 id="authorities-inspected" tabindex="-1">Authorities inspected <a class="header-anchor" href="#authorities-inspected" aria-label="Permalink to &quot;Authorities inspected&quot;">​</a></h2><ul><li>B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, UBS Publishers&#39; Distributors, 1993, is the bibliographic work. Its Chapter XVII passage, “Filing law-suits,” was inspected in the distinct 2020 Chistabo derivative at internal printed page 67 (physical PDF page 71).</li><li>Rama Daivajna, <em>Muhurta Chintamani</em>, undated Sanskrit text with Hindi commentary, Shubhashubha-prakarana, verses 43–45, printed pages 20–21 (Internet Archive OCR lines 1743–1797).</li></ul><p>Raman supplies the narrow lawsuit-filing election. Chintamani verse 44 calls the specified Puchha periods auspicious generally; it does not name litigation or authorize an activity-specific score.</p><h2 id="corrected-shared-computation" tabindex="-1">Corrected shared computation <a class="header-anchor" href="#corrected-shared-computation" aria-label="Permalink to &quot;Corrected shared computation&quot;">​</a></h2><p>The project now locates five-Ghati Mukha and three-Ghati Puchha in verse 44&#39;s Tithi-specific numbered Yamas, expressed as quarters of the observed Vishti duration. The verified shared claim is <code>panchangam.bhadra_mukha_puchha</code>.</p><p>That correction does not create a legal-election rule. The Court profile has no Bhadra Puchha bonus because Raman&#39;s filing passage supplies none and Chintamani verse 44 names no litigation activity.</p><h2 id="safety" tabindex="-1">Safety <a class="header-anchor" href="#safety" aria-label="Permalink to &quot;Safety&quot;">​</a></h2><p>Legal deadlines, court rules, counsel, evidence and personal safety always take precedence. Electional timing cannot predict or guarantee a legal result.</p>',12)])])}const m=a(o,[["render",s]]);export{p as __pageData,m as default};
